inputs.script:
const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
await sleep(3500);
const img=document.querySelector("#siwp_captcha_image_0")||document.querySelector("img[id^=siwp_captcha_image]");
if(!img) return {stop_workflow:true, stop_reason:"captcha image not found"};
const until=Date.now()+10000;
while(Date.now()<until&&!(img.complete&&img.naturalWidth>0)) await sleep(200);
const c=document.createElement("canvas");c.width=img.naturalWidth;c.height=img.naturalHeight;
c.getContext("2d").drawImage(img,0,0);
return {image:c.toDataURL("image/png"),width:c.width,height:c.height};
